// Soporta dos modos:
// 1) body.chunks: [{text, metadata}, ...]  -> pre-procesados (CLI/UI con paginas reales)
// 2) body.text: "..."                       -> chunkea aqui (compatibilidad)
const wh = $input.first();
const body = wh.json.body || {};
const archivo = body.archivo || 'documento.txt';
const proyecto = body.proyecto || 'default';
const tipo = body.tipo || 'texto';
const total_paginas = body.total_paginas || 1;
const path_original = body.path_original || '';

// Modo 1: chunks ya vienen armados
if (Array.isArray(body.chunks) && body.chunks.length) {
  return body.chunks.map((c, i) => ({
    json: {
      id: c.id || `${proyecto}__${archivo}__chunk_${i}`,
      text: c.text,
      metadata: {
        archivo, proyecto, tipo, path_original, total_paginas,
        ...(c.metadata || {}),
        chunk_index: c.metadata?.chunk_index ?? i,
      }
    }
  }));
}

// Modo 2: text crudo -> chunking aqui
const text = body.text || '';
const CHUNK_SIZE = 1000;
const OVERLAP = 200;
const chunks = [];
let i = 0, chunkIndex = 0;
while (i < text.length) {
  const end = Math.min(i + CHUNK_SIZE, text.length);
  const pagina_aprox = total_paginas > 1 ? Math.floor((i / Math.max(text.length, 1)) * total_paginas) + 1 : 1;
  chunks.push({
    json: {
      id: `${proyecto}__${archivo}__chunk_${chunkIndex}`,
      text: text.slice(i, end),
      metadata: { archivo, proyecto, tipo, chunk_index: chunkIndex, char_start: i, char_end: end, pagina_aprox, pagina: pagina_aprox, total_paginas, path_original }
    }
  });
  chunkIndex++;
  if (end >= text.length) break;
  i += CHUNK_SIZE - OVERLAP;
}
if (chunks.length === 0) {
  throw new Error('Texto vacio - nada que indexar');
}
return chunks;

const res = $input.first().json;
const items = $('Prep batch embeddings').first().json.items;
if (!res.data || res.data.length !== items.length) {
  throw new Error(`Embedding count mismatch: got ${res.data?.length}, expected ${items.length}`);
}
return items.map((item, i) => ({ json: { ...item, embedding: res.data[i].embedding } }));

const items = $input.all();
return [{ json: {
  ids: items.map(i => i.json.id),
  embeddings: items.map(i => i.json.embedding),
  documents: items.map(i => i.json.text),
  metadatas: items.map(i => i.json.metadata),
}}];

// NIVEL 1: generar resumen del archivo + indexar en coleccion 'indice'
// (entender de que va cada archivo sin tener que leerlo entero al consultar).
const items = $('Normalize input').all();
if (items.length === 0) return [{ json: { skip_indice: true } }];

const body = $('Webhook Texto').first().json.body || {};
const archivo = body.archivo || items[0].json?.metadata?.archivo || 'documento';
const proyecto = body.proyecto || items[0].json?.metadata?.proyecto || 'default';
const tipo = body.tipo || items[0].json?.metadata?.tipo || 'texto';
const total_paginas = body.total_paginas || 1;
const path_original = body.path_original || '';
const n_chunks = items.length;

// Concatenar texto (con muestreo si es muy grande - tomar primer y ultimo chunk)
let textoCompleto = items.map(it => it.json.text).join('\n\n');
if (textoCompleto.length > 12000) {
  // Sampling: primeros 6000 + ultimos 4000
  const head = textoCompleto.slice(0, 6000);
  const tail = textoCompleto.slice(-4000);
  textoCompleto = head + '\n\n[...contenido omitido por brevedad...]\n\n' + tail;
}

// Llamar al LLM para generar resumen estructurado
const sysPrompt = `Sos un indexador de archivos. Te paso el contenido (o muestra) de un archivo. Tu tarea: producir un resumen estructurado que despues servira como 'mapa' para que otro agente decida si vale la pena leer este archivo cuando responda preguntas del usuario.

Devolve JSON exacto:
{
  "tema_principal": "que es este archivo en 1 linea",
  "resumen": "3-5 oraciones describiendo el contenido y para que sirve",
  "entidades_clave": ["nombres propios, productos, funciones, queries, modulos clave"],
  "conceptos": ["temas/dominios que cubre"]
}
Se especifico, no genericalices. Usa el lenguaje del propio archivo.`;

const userPrompt = `Archivo: ${archivo} (tipo: ${tipo}, ${n_chunks} chunks)\n\nContenido:\n\n${textoCompleto}`;

let resumen, tema, entidades = [], conceptos = [];
try {
  const llm = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://openrouter.ai/api/v1/chat/completions',
    headers: {
      'Authorization': `Bearer ${$env.OPENROUTER_API_KEY}`,
      'Content-Type': 'application/json',
      'HTTP-Referer': 'http://localhost',
      'X-Title': 'CoWorkerIA Indexer',
    },
    body: {
      model: 'openai/gpt-4o-mini',
      messages: [
        { role: 'system', content: sysPrompt },
        { role: 'user', content: userPrompt },
      ],
      max_tokens: 600,
      temperature: 0,
    },
    json: true,
  });
  const raw = llm.choices?.[0]?.message?.content || '{}';
  let parsed;
  try { parsed = JSON.parse(raw); }
  catch {
    const cleaned = raw.replace(/^```(?:json)?\s*/gm, '').replace(/```\s*$/gm, '').trim();
    try { parsed = JSON.parse(cleaned); } catch { parsed = {}; }
  }
  tema = parsed.tema_principal || archivo;
  resumen = parsed.resumen || '';
  entidades = Array.isArray(parsed.entidades_clave) ? parsed.entidades_clave.slice(0, 15) : [];
  conceptos = Array.isArray(parsed.conceptos) ? parsed.conceptos.slice(0, 10) : [];
} catch (e) {
  // Si falla, no indexamos en el indice (pero los chunks ya estan en Chroma principal)
  return [{ json: { skip_indice: true, error: String(e) } }];
}

// Texto para embedear: incluye tema + resumen + entidades + conceptos
// (asi la similitud con la pregunta del usuario es robusta)
const textoIndice = `Archivo: ${archivo}\nTema: ${tema}\nResumen: ${resumen}\nEntidades: ${entidades.join(', ')}\nConceptos: ${conceptos.join(', ')}`;

// Embedear ese texto
const emb = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://openrouter.ai/api/v1/embeddings',
  headers: {
    'Authorization': `Bearer ${$env.OPENROUTER_API_KEY}`,
    'Content-Type': 'application/json',
  },
  body: { input: [textoIndice], model: $env.EMBED_MODEL || 'openai/text-embedding-3-small' },
  json: true,
});
const embedding = emb.data?.[0]?.embedding;
if (!embedding) return [{ json: { skip_indice: true, error: 'No embedding' } }];

// ID determinista por archivo+proyecto (asi re-ingestar sobreescribe)
const id = `indice__${proyecto}__${archivo}`;

// Postear/upsert al indice (Chroma /add fallaria por duplicate id; usamos /upsert)
await this.helpers.httpRequest({
  method: 'POST',
  url: `http://localhost:8000/api/v2/tenants/default_tenant/databases/default_database/collections/${$env.CHROMA_INDICE_ID}/upsert`,
  headers: { 'Content-Type': 'application/json' },
  body: {
    ids: [id],
    embeddings: [embedding],
    documents: [textoIndice],
    metadatas: [{
      archivo, proyecto, tipo, n_chunks, total_paginas, path_original,
      tema, resumen,
      entidades: entidades.join(' | '),
      conceptos: conceptos.join(' | '),
      indexed_at: new Date().toISOString(),
    }],
  },
  json: true,
});

return [{ json: { indice_ok: true, archivo, tema, resumen } }];
